import type { Readable } from 'node:stream';

export const OBJECT_STORAGE = Symbol('OBJECT_STORAGE');

/** Keys are generated by the server only: `farms|facilities/<numeric id>/media/<uuid>.<jpg|png|webp>`. */
export const STORAGE_KEY_PATTERN =
  /^(farms|facilities)\/[1-9]\d{0,18}\/media\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|png|webp)$/;

export class InvalidStorageKeyError extends Error {}
export class StorageObjectNotFoundError extends Error {}

/**
 * Private object storage. Implementations must never expose objects publicly: the API streams them after its own
 * authorization checks. A future S3-compatible adapter implements this same interface (private bucket, no ACLs, SSE).
 */
export interface ObjectStorage {
  /** Stores a new object. Must not overwrite an existing key. */
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  /** @throws StorageObjectNotFoundError / InvalidStorageKeyError */
  get(key: string): Promise<{ stream: Readable; size: number }>;
  /** Idempotent: deleting a missing object is not an error. */
  delete(key: string): Promise<void>;
}

export function assertValidStorageKey(key: string): void {
  if (!STORAGE_KEY_PATTERN.test(key)) throw new InvalidStorageKeyError('Invalid storage key');
}
